#include<stdio.h>
#include<stdlib.h>
#include<string.h>
#define V 50257
#define M 50000
unsigned char tb[4000000];int to[V],tl[V],np1[M],np2[M];
#define HN 131072
int ht[HN],u2b[512],b2t[256];
unsigned Hh(unsigned char*s,int n){unsigned h=2166136261;for(int i=0;i<n;i++){h^=s[i];h*=16777619;}return h;}
int find(unsigned char*s,int n){unsigned h=Hh(s,n);for(int i=h%HN;;i=(i+1)%HN){if(!ht[i])return-1;int id=ht[i]-1;if(tl[id]==n&&!memcmp(tb+to[id],s,n))return id;}}
void add(int id){unsigned h=Hh(tb+to[id],tl[id]);for(int i=h%HN;;i=(i+1)%HN)if(!ht[i]){ht[i]=id+1;return;}}
void loadbpe(char*fn){int k=0,p=0,t=0;
for(int i=33;i<127;i++){u2b[i]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;}
for(int i=161;i<173;i++){u2b[i]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;}
for(int i=174;i<256;i++){u2b[i]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;}
for(int i=0;i<=32;i++){u2b[256+k]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;k++;}
for(int i=127;i<=160;i++){u2b[256+k]=i;b2t[i]=t;to[t]=p;tb[p++]=i;tl[t]=1;add(t);t++;k++;}
u2b[256+k]=173;b2t[173]=t;to[t]=p;tb[p++]=173;tl[t]=1;add(t);
FILE*f=fopen(fn,"rb");char ln[512];fgets(ln,512,f);
for(int r=0;r<M;r++){fgets(ln,512,f);int sp=0;while(ln[sp]!=' ')sp++;
unsigned char b[64];int n=0;
for(int i=0;i<sp;){int c=ln[i];if(c<128)b[n++]=u2b[c],i++;else{b[n++]=u2b[((c&31)<<6)|(ln[i+1]&63)];i+=2;}}
int id1=find(b,n);n=0;int l2=strlen(ln+sp+1)-1;
for(int i=0;i<l2;){int c=ln[sp+1+i];if(c<128)b[n++]=u2b[c],i++;else{b[n++]=u2b[((c&31)<<6)|(ln[sp+1+i+1]&63)];i+=2;}}
int id2=find(b,n);int id=256+r;to[id]=p;memcpy(tb+p,tb+to[id1],tl[id1]);p+=tl[id1];memcpy(tb+p,tb+to[id2],tl[id2]);p+=tl[id2];tl[id]=p-to[id];add(id);np1[r]=id1;np2[r]=id2;}
fclose(f);}
int main(int c,char**a){loadbpe(a[1]);
 printf("b2t[32]=%d b2t[119]=%d\n",b2t[32],b2t['w']);
 printf("tok 220 bytes:");for(int i=0;i<tl[220];i++)printf(" %d",tb[to[220]+i]);printf("\n");
 printf("tok 86 bytes:");for(int i=0;i<tl[86];i++)printf(" %d",tb[to[86]+i]);printf("\n");
 printf("tok 995 bytes:");for(int i=0;i<tl[995];i++)printf(" %d",tb[to[995]+i]);printf("\n");
 printf("np1[739]=%d np2[739]=%d\n",np1[739],np2[739]);
 int r=0;while(r<M&&!(np1[r]==220&&np2[r]==86))r++;
 printf("merge(220,86) at r=%d %s\n",r,r<M?"FOUND":"NOT FOUND");
 r=0;while(r<M&&!(np1[r]==220&&np2[r]==6894))r++;
 printf("merge(220,6894) at r=%d %s\n",r,r<M?"FOUND":"NOT FOUND");
 printf("tok 6894 bytes:");for(int i=0;i<tl[6894];i++)printf(" %d",tb[to[6894]+i]);printf("\n");
 return 0;}
EOF
